def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] != bg:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append(cells)
    shapes = []
    for cells in objects:
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        r0, r1, c0, c1 = min(ys), max(ys), min(xs), max(xs)
        base = Counter(grid[y][x] for y, x in cells).most_common(1)[0][0]
        patch = [[grid[y][x] for x in range(c0, c1 + 1)] for y in range(r0, r1 + 1)]
        special = sum(grid[y][x] != base for y, x in cells)
        shapes.append((patch, base, special))
    patch, base, _ = max(shapes, key=lambda z: z[2])
    out = [row[:] for row in patch]
    for other, obase, _ in shapes:
        if other is patch:
            continue
        for y in range(min(len(out), len(other))):
            for x in range(min(len(out[0]), len(other[0]))):
                if other[y][x] != obase:
                    out[y][x] = other[y][x]
    return out
